    private String loginAnnouncementHtml() {
        return "<button class='login-ann-btn' type='button' onclick='openLoginAnnouncementList()'>公告</button>"
                + "<div class='login-ann-overlay' id='loginAnnOverlay'>"
                + "<div class='login-ann-backdrop' onclick='closeLoginAnnouncement()'></div>"
                + "<div class='login-ann-sheet'>"
                + "<div class='login-ann-side'><div class='login-ann-side-title'>公告</div><div class='login-ann-side-sub'>查看服务器最新通知、版本变化与维护安排。</div><div class='login-ann-list' id='loginAnnList'><div class='login-ann-empty'>正在加载公告...</div></div></div>"
                + "<div class='login-ann-main'><div class='login-ann-main-head'><div><div class='login-ann-title' id='loginAnnTitle'>服务器公告</div><div class='login-ann-meta' id='loginAnnMeta'>加载中...</div></div><button class='login-ann-close' type='button' onclick='closeLoginAnnouncement()'>×</button></div><div class='login-ann-main-body'><div class='login-md' id='loginAnnContent'><div class='login-ann-empty'>正在加载公告...</div></div></div></div>"
                + "</div></div>";
    }

    private String loginAnnouncementScript() {
        return "let loginAnnouncementItems=[];let loginAnnouncementActiveId='';"
                + "function loginAnnEsc(v){return String(v==null?'':v).replace(/[&<>\\\"']/g,m=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",\"\\\"\":\"&quot;\",\"'\":\"&#39;\"}[m]||m));}"
                + "function loginAnnFmt(v){if(!v)return'-';try{return new Date(v).toLocaleString('zh-CN');}catch(e){return'-';}}"
                + "function loginAnnMd(text){let html=loginAnnEsc(text||'');html=html.replace(/```(\\w*)\\n([\\s\\S]*?)```/g,(_,lang,code)=>'<pre><code>'+code+'</code></pre>');html=html.replace(/`([^`]+)`/g,'<code>$1</code>');html=html.replace(/^### (.+)$/gm,'<h4>$1</h4>');html=html.replace(/^## (.+)$/gm,'<h3>$1</h3>');html=html.replace(/^# (.+)$/gm,'<h2>$1</h2>');html=html.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>');html=html.replace(/\\*(.+?)\\*/g,'<em>$1</em>');html=html.replace(/^[-*] (.+)$/gm,'<li>$1</li>');html=html.replace(/(<li>[\\s\\S]*?<\\/li>)/g,'<ul>$1</ul>');html=html.replace(/<\\/ul>\\s*<ul>/g,'');html=html.replace(/^> (.+)$/gm,'<blockquote>$1</blockquote>');html=html.replace(/<\\/blockquote>\\s*<blockquote>/g,'<br>');html=html.replace(/\\[([^\\]]+)\\]\\(([^)]+)\\)/g,'<a href=\"$2\" target=\"_blank\" rel=\"noopener\">$1</a>');html=html.replace(/\\n/g,'<br>');return html;}"
                + "async function loginAnnApi(url){const r=await fetch(url,{cache:'no-store'});let d={};try{d=await r.json();}catch(e){throw new Error('服务器返回了无法解析的内容');}if(!r.ok||(d&&d.error))throw new Error((d&&d.error)||'加载失败');return d;}"
                + "function renderLoginAnnouncementCards(items){const list=document.getElementById('loginAnnList');if(!list)return;list.innerHTML=Array.isArray(items)&&items.length?items.map(item=>'<button type=\"button\" class=\"login-ann-item '+(item.id===loginAnnouncementActiveId?'active':'')+'\" onclick=\"selectLoginAnnouncement(\\''+loginAnnEsc(item.id)+'\\')\"><div class=\"login-ann-item-title\">'+loginAnnEsc(item.title||'系统公告')+'</div><div class=\"login-ann-item-meta\">'+loginAnnFmt(item.updatedAt||item.createdAt)+'<br>@'+loginAnnEsc(item.authorNickname||'系统')+'</div></button>').join(''):'<div class=\"login-ann-empty\">当前还没有公告</div>';}"
                + "function renderLoginAnnouncementContent(item){document.getElementById('loginAnnTitle').textContent=item&&item.title?item.title:'服务器公告';document.getElementById('loginAnnMeta').textContent=item&&item.id?('发布于 '+loginAnnFmt(item.updatedAt||item.createdAt)+' · 发布者 '+(item.authorNickname||'系统')):'暂无公告';document.getElementById('loginAnnContent').innerHTML=item&&item.id?loginAnnMd(item.content||''):'<div class=\"login-ann-empty\">当前还没有公告</div>';}"
                + "function selectLoginAnnouncement(id){loginAnnouncementActiveId=id||'';const item=(loginAnnouncementItems||[]).find(v=>v.id===loginAnnouncementActiveId)||(loginAnnouncementItems||[])[0]||null;renderLoginAnnouncementCards(loginAnnouncementItems||[]);renderLoginAnnouncementContent(item);}"
                + "async function loadLoginAnnouncements(preferredId){const list=await loginAnnApi('/api/announcements');loginAnnouncementItems=Array.isArray(list)?list:[];loginAnnouncementActiveId=preferredId||((loginAnnouncementItems[0]||{}).id||'');renderLoginAnnouncementCards(loginAnnouncementItems);selectLoginAnnouncement(loginAnnouncementActiveId);}"
                + "async function openLoginAnnouncementList(preferredId){document.getElementById('loginAnnOverlay').classList.add('show');try{await loadLoginAnnouncements(preferredId);}catch(e){document.getElementById('loginAnnList').innerHTML='<div class=\"login-ann-empty\">'+loginAnnEsc(e.message||'加载失败')+'</div>';document.getElementById('loginAnnContent').innerHTML='<div class=\"login-ann-empty\">'+loginAnnEsc(e.message||'加载失败')+'</div>';document.getElementById('loginAnnMeta').textContent='公告加载失败';}}"
                + "function closeLoginAnnouncement(){document.getElementById('loginAnnOverlay').classList.remove('show');}"
                + "async function bootLoginAnnouncements(){try{const latest=await loginAnnApi('/api/announcements/latest');if(latest&&latest.id){const key='login_announcement_seen_id';if(localStorage.getItem(key)!==latest.id){localStorage.setItem(key,latest.id);openLoginAnnouncementList(latest.id);}}}catch(e){}}"
                + "document.addEventListener('keydown',e=>{if(e.key==='Escape')closeLoginAnnouncement();});bootLoginAnnouncements();";
    }

