    private String renderChatPage(User user) {
        java.util.Map<String, Object> meData = new java.util.LinkedHashMap<>();
        meData.put("userId", user.getUserId());
        meData.put("username", user.getUsername());
        meData.put("nickname", user.getNickname());
        meData.put("avatarPath", user.getAvatarPath());
        meData.put("bubbleSkin", user.getBubbleSkin());
        meData.put("messageFont", user.getMessageFont());
        meData.put("language", user.getLanguage() != null ? user.getLanguage() : "zh-CN");
        meData.put("isSuperAdmin", isSuperAdmin(user.getUserId()));
        meData.put("isPrimarySuperAdmin", isPrimarySuperAdmin(user.getUserId()));
        meData.put("isDeveloper", isDeveloper(user.getUserId()));
        meData.put("banned", user.isCurrentlyBanned());
        meData.put("banExpiresAt", user.getBanExpiresAt());
        meData.put("banReason", user.getBanReason());
        meData.put("level", user.getEffectiveLevel());
        meData.put("levelDisplay", user.getLevelDisplay());
        meData.put("exp", user.getExp());
        meData.put("lastCheckIn", user.getLastCheckIn());
        meData.put("checkInStreak", user.getCheckInStreak());
        meData.put("dailyGamePlayExpCount", java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai"))
                .toString().equals(user.getGamePlayExpDay()) ? user.getDailyGamePlayExpCount() : 0);
        meData.put("dailyGamePlayExpLimit", 3);
        meData.put("nextLevelExp", getNextLevelExp(user));
        meData.put("cloudQuotaByLevel", user.getCloudQuotaByLevel() == Long.MAX_VALUE ? -1 : user.getCloudQuotaByLevel());
        meData.put("aiDailyLimitByLevel", user.getAiDailyLimitByLevel() == Double.MAX_VALUE ? -1 : (long) user.getAiDailyLimitByLevel());
        meData.put("dailyGameUploadLimitByLevel", user.getDailyGameUploadLimitByLevel());
        meData.put("msgsPerMinuteByLevel", user.getMsgsPerMinuteByLevel());
        meData.put("aiUsedTokensToday", user.getAiUsedTokensToday());
        meData.put("aiRemainingTokens", AiService.getInstance().getRemainingTokens(user) == Double.MAX_VALUE
                ? -1 : AiService.getInstance().getRemainingTokens(user));
        meData.put("featureBans", UserService.getInstance().getAllFeatureBanInfo(user.getUserId()));
        String meJson = inlineJson(meData);
        String superAdminIdsJson = inlineJson(superAdminService.listSuperAdminIds());
        return "<!DOCTYPE html><html lang='zh-CN'><head>"
                + "<meta charset='UTF-8'>"
                + "<meta name='viewport' content='width=device-width,initial-scale=1'>"
                + "<title>聊天</title>"
                + "<link rel='icon' href='/favicon.ico'>"
                + "<link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github-dark.min.css'>"
                + "<link rel='stylesheet' href='https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/katex.min.css'>"
                + "<script src='https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js'></script>"
                + "<script src='https://cdnjs.cloudflare.com/ajax/libs/marked/9.1.6/marked.min.js'></script>"
                + "<script src='https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/katex.min.js'></script>"
                + "<script src='https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/contrib/auto-render.min.js'></script>"
                + "<script src='https://cdnjs.cloudflare.com/ajax/libs/monaco-editor/0.44.0/min/vs/loader.min.js'></script>"
                + "<link rel='stylesheet' href='/assets/app-extra.css'>"
                + "<link rel='stylesheet' href='https://cdn.jsdelivr.net/npm/markdown-palettes@0.4.13/dist/markdown-palettes.css'>"
                + "<style>" + CSS() + "</style>"
                + "<link rel='stylesheet' href='/assets/wechat-theme.css?v=20260728-apple6'>"
                + "<script src='/assets/app-icons.js?v=" + String.valueOf(System.currentTimeMillis()) + "'></script>"
                + "</head><body>"
                + topbar(user) + "<div class='main'>" + sidebar()
                + "<div class='chat-area' id='chatArea'>"
                + viewChat() + viewDiscover() + viewMoments() + viewProfile() + viewGames()
                + viewNotes() + viewServerAdmin() + viewUserProfile()
                + viewCloud() + viewAi() + viewMusic() + viewVideos() + viewFeedback()
                + viewFeatures()
                + "</div></div>"
                + modals()
                + "<script src='https://cdn.jsdelivr.net/npm/markdown-palettes@0.4.13/dist/markdown-palettes.min.js'></script>"
                + "<script>window.ME=" + meJson + ";\nwindow.SUPER_ADMIN_IDS=" + superAdminIdsJson + ";\n" + JS() + "\n</script>"
                + "<script src='/assets/app-i18n.js?v=" + String.valueOf(System.currentTimeMillis()) + "'></script>"
                + "<script>initI18n(ME && ME.language ? ME.language : 'zh-CN');</script>"
                + "<script src='/assets/app-extra.js?v=" + String.valueOf(System.currentTimeMillis()) + "'></script>"
                + "</body></html>";
    }

