    private String topbar(User user) {
        String av = user.getAvatarPath() != null && !user.getAvatarPath().isEmpty()
                ? "<img src='" + eH(user.getAvatarPath())
                        + "' style='width:32px;height:32px;border-radius:50%;object-fit:cover;border:2px solid rgba(255,255,255,.5)'>"
                : "<div style='width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,.3);display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700'>"
                        + eH(String.valueOf(user.getNickname().charAt(0)).toUpperCase()) + "</div>";
        String badges = "";
        if (isPrimarySuperAdmin(user.getUserId())) {
            badges += " <span class='owner-b'>服主</span>";
        }
        if (isSuperAdmin(user.getUserId())) {
            badges += " <span class='sa-b'>⭐超管</span>";
        }
        if (isDeveloper(user.getUserId())) {
            badges += " <span class='developer-b'>开发者</span>";
        }
        String levelBadge = " <span class='lv-badge lv-" + user.getEffectiveLevel() + "'>" + eJ(user.getLevelDisplay()) + "</span>";
        return "<div class='topbar'>"
                + "<div class='app-brand-mark'><img class='feature-icon-image' src='/assets/icons/generated/brand-chat.png' alt='聊天'><h1>聊天</h1></div>"
                + "<div class='tb-r'>"
                + "<button class='tb-btn rail-action' onclick='openAnnouncements()' title='公告'><img class='rail-icon-image' src='/assets/icons/generated/notes.png' alt=''><span>公告</span></button>"
                + "<button class='tb-btn rail-action' onclick='openSearch()' title='搜索'><svg class='rail-native-icon' viewBox='0 0 24 24' aria-hidden='true'><circle cx='10.5' cy='10.5' r='6.5'></circle><path d='m15.4 15.4 4.1 4.1'></path></svg><span>搜索</span></button>"
                + "<div class='tb-user'>" + av
                + "<span>" + eH(user.getNickname()) + badges + levelBadge
                + "</span></div>"
                + (isSuperAdmin(user.getUserId())
                ? "<button class='tb-btn rail-action' onclick='openServerAdmin()' title='服务器管理'><img class='rail-icon-image' src='/assets/icons/generated/admin.png' alt=''><span>管理</span></button>" : "")
                + "<button class='tb-btn rail-action' onclick='openFeedback()' title='联系我们/反馈'><img class='rail-icon-image' src='/assets/icons/generated/feedback.png' alt=''><span>反馈</span></button>"
                + "<button class='tb-btn rail-action' onclick='openProfile()' title='个人中心'><img class='rail-icon-image' src='/assets/icons/generated/profile.png' alt=''><span>我的</span></button>"
                + "<button class='logout-btn rail-action rail-action-logout' onclick='logout()' title='退出'><svg class='rail-native-icon' viewBox='0 0 24 24' aria-hidden='true'><path d='M10 5H5v14h5M14 8l4 4-4 4M18 12H9'></path></svg><span>退出</span></button></div></div>\n";
    }

